fun readName(msg: ByteArray, offset: Int): Pair<String, Int> {
    val labels = mutableListOf<String>()
    var at = offset
    var end = -1                                         // end of the name where we started
    while (true) {
        val len = msg[at].toInt() and 0xff
        when {
            len == 0 -> {                                // the root: done
                if (end < 0) end = at + 1
                return labels.joinToString(".") to end
            }
            len and 0xc0 == 0xc0 -> {                    // compression pointer
                val target = ((len and 0x3f) shl 8) or (msg[at + 1].toInt() and 0xff)
                require(target < at) { "pointer at $at does not point backwards" }
                if (end < 0) end = at + 2                // the pointer is the last 2 bytes here
                at = target
            }
            else -> {                                    // an ordinary label
                labels += String(msg, at + 1, len, Charsets.US_ASCII)
                at += 1 + len
            }
        }
    }
}

// After a pointer the rest of the name lives elsewhere in the message, so the next field
// starts 2 bytes after the first pointer, not after the last label read.
